def on_page(c, doc):
    c.saveState(); c.setFont("DVS", 7.8); c.setFillColor(MUTED)
    c.drawString(doc.leftMargin, 0.42*inch, "The Hero of Time  ·  D&D 5th Edition build (2024 rules; the items, songs and masks are homebrew)")
    c.drawRightString(letter[0]-doc.rightMargin, 0.42*inch, f"page {doc.page}"); c.restoreState()
doc = SimpleDocTemplate("../pdf/Hero_of_Time_5e_Build.pdf", pagesize=letter, leftMargin=0.6*inch, rightMargin=0.6*inch, topMargin=0.6*inch, bottomMargin=0.7*inch, title="The Hero of Time — D&D 5e Build", author="Claude")
W = letter[0] - 1.2*inch; S = []
S.append(P("Link, the Hero of Time", title))
S.append(P("Hylian · Fighter (Battle Master) 20 · Kokiri foundling · the Master Sword, the Ocarina, the masks, and the courage that never asked for anything", subtitle))
S.append(HRFlowable(width="100%", thickness=1.4, color=GREEN, spaceBefore=4, spaceAfter=8))
S.append(P("Built on the 2024 rules, canon-first. Sources: Ocarina of Time, Majora's Mask, and Twilight Princess for the Hero's Shade; Hyrule Historia for the parts between. The boy who saved three peoples and drew the sword; the man who woke seven years later and freed six Sages and a kingdom; the boy again, in a land with three days to live, who saved it and gave the moon back to the sky; the knight who went home to a Hyrule that didn't remember and died with that; the shade who taught the next one everything, and then could rest."))
S.append(P("<b>Design calls.</b> Pure Fighter, because he is one: no class of his has ever cast a thing. Battle Master, because the seven Hidden Skills he taught the Hero of Twilight are maneuvers, and the Spin Attack is one too. Dexterity for the bow and the roll; the Master Sword is written as Finesse because it is his. Everything that looks like magic on this sheet is an item or a song: three spells from three Great Fairies on a Magic Meter, an Ocarina with a page of songs, and a bag of masks. Tough is the twenty hearts. He is Lawful Good and silent; his Charisma is 8 and the whole kingdom still follows him. The Fierce Deity's Mask works only in a boss's lair, as in the game, so it is on the sheet and not in the arena."))
S.append(P("Snapshot: the Hero in his prime, level 20 (Fighter 20)", h2)); S.append(rule())
block = [P("Link, the Hero of Time", statname),
 P("Medium Humanoid (Hylian), seventeen when he woke, a knight of Hyrule by the end · the green tunic and cap, the Master Sword and the Hylian Shield, the Fairy Bow, a hookshot, four bottles, and the Ocarina of Time · Navi, when she was there", stattag),
 P("<b>AC</b> 20 (the tunic over mail as +1 studded leather, the Hylian Shield +1) · <b>HP</b> 224 (twenty hearts, Tough) · <b>Speed</b> 30 ft, 45 in the Bunny Hood, swim and climb at full speed (Athlete, the Zora Tunic) · <b>Initiative</b> +11 (Alert) · <b>Proficiency</b> +6", stat),
 abil_table(["14 (+2)","20 (+5)","16 (+3)","10 (+0)","16 (+3)","8 (−1)"], W-24), Spacer(1,4),
 P("<b>Saves</b> Str +8, Con +9; Indomitable ×3; immune to being Frightened (the Triforce of Courage), and once per long rest a failed save becomes a success · <b>Skills</b> Perception +15 (expertise), Athletics +8, Acrobatics +11, Survival +9, Animal Handling +9, Stealth +11 · <b>Tools</b> the ocarina · <b>Save DC</b> 19 for maneuvers, 18 for items and songs", stat),
 P("<b>Attacks</b> (four per Attack action; Action Surge twice a fight). <b>Master Sword</b> +14, 1d8+10 slashing (1d10+10 in two hands); against fiends, undead and creatures of evil, +2d8 radiant: the Blade of Evil's Bane. <b>Fairy Bow</b> +12, 1d8+6 piercing, 150/600, no penalty at range or point-blank (Sharpshooter). <b>Fire Arrow</b> +2d6 fire and Burning, <b>Ice Arrow</b> +2d6 cold and Con DC 18 or Restrained for a round, <b>Light Arrow</b> +3d8 radiant and, against a creature of evil, Con DC 18 or Stunned until the end of its next turn (one Magic each). <b>Biggoron's Sword</b> +12, 2d6+8, two hands, no shield. <b>Megaton Hammer</b> +12, 2d6+8, and every creature within 5 ft of the blow makes a Str save DC 18 or falls prone. <b>Longshot</b> +12, 1d6+5, and he is pulled to the target or it to him, 120 ft. <b>Boomerang</b> +12, 1d4+5, returns, and a Small or smaller creature is Stunned for a round. Boon of Combat Prowess: once a turn, a miss with the sword hits.", stat),
 P("<b>Items that replace one attack.</b> <b>Deku Nut:</b> a flash in a 10-ft radius, Con DC 18 or Stunned until the end of its next turn (he carries ten). <b>Bomb:</b> 10-ft radius within 60 ft, Dex DC 18, 3d6 fire, half on a save; a <b>Bombchu</b> runs 60 ft along any surface first. <b>Spin Attack:</b> every creature within 5 ft (10 ft for the Great Spin, at full health) takes the sword's damage, Dex DC 19 for half.", stat),
 P("<b>Maneuvers</b> (six d12, back on a short rest; one free d8 a turn from Relentless): the seven Hidden Skills and two more. <b>Ending Blow</b> (Trip Attack, and a hit on a prone creature is a critical hit), <b>Shield Attack</b> (Pushing Attack with the shield), <b>Back Slice</b> (Feinting Attack), <b>Helm Splitter</b> (Precision Attack; a shield adds nothing against it), <b>Mortal Draw</b> (Riposte; against a creature that has not yet acted this fight, the hit is a critical), <b>Jump Strike</b> (Lunging Attack), <b>Great Spin</b> (Sweeping Attack), Parry, Evasive Footwork. Shield Master: a bash after any melee hit, Str DC 19 or prone.", stat),
 P("<b>The Magic Meter: 12 a day.</b> <b>Din's Fire</b> (2): a 20-ft dome of flame around him, Dex DC 18, 8d6 fire, half on a save, and he takes none. <b>Farore's Wind</b> (2): mark a spot; later, as an action, be there again. <b>Nayru's Love</b> (3): for 1 minute he takes no damage from anything. He can still be moved, knocked down, stunned, put to sleep or held, and anything that is written to ignore immunity gets through. <b>Lens of Truth</b> (1 a minute): truesight 60 ft.", stat),
 P("<b>Bottles (four).</b> A <b>fairy</b> brings him back from 0 hit points at 90 the moment he drops, no action. A <b>red potion</b> (bonus action) is full hit points; a <b>blue potion</b> is full hit points and a full Magic Meter. Default: two fairies, one of each potion.", stat),
 P("<b>Feats</b> Alert, Tough, Dueling, Sharpshooter, Shield Master, +2 Dexterity, Athlete, Durable, Skill Expert (Perception), Boon of Combat Prowess · <b>Other</b> Second Wind ×4 (1d10+20), Know Your Enemy, Studied Attacks, Tactical Master, Master Sword reflection, the Hylian Shield (page 2), the Ocarina and the masks (page 2).", stat),
 P("<b>How he fights.</b> Nayru's Love when the thing in front of him can kill him, then the sword. A Deku Nut and an Ending Blow is the oldest combination in Hyrule. Back Slice for the opening, Helm Splitter for the armor, Shield Attack for the space, Mortal Draw for the thing that charges. The bow for what he cannot reach, the Light Arrow for what is evil, and the hookshot for the wall behind it. He will not speak. He will not stop. He has never once asked what it costs.", stat)]
box = Table([[f] for f in block], colWidths=[W]); box.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("BOX",(0,0),(-1,-1),1.0,GREEN),("LEFTPADDING",(0,0),(-1,-1),11),("RIGHTPADDING",(0,0),(-1,-1),11),("TOPPADDING",(0,0),(-1,-1),1),("BOTTOMPADDING",(0,0),(-1,-1),1),("TOPPADDING",(0,0),(-1,0),9),("BOTTOMPADDING",(0,-1),(-1,-1),9)])); S.append(box)
S.append(P("What he carries, and what it does", h2)); S.append(rule())
hb = [("The Master Sword", "legendary · Finesse longsword, +3; no creature of evil can hold it", "The Blade of Evil's Bane: +2d8 radiant against fiends, undead and creatures of evil, and a hit on such a creature ends any possession or magical disguise on it. <b>Reflection:</b> when a ranged spell attack or a magical bolt is made against him, he can use his reaction to bat it back at its source with his own attack roll; the volley with Ganondorf was exactly this. <b>Spin Attack</b> (above). Drawn from the pedestal, it put him to sleep for seven years, because the hero was too young."),
 ("The Hylian Shield and the Mirror Shield", "the Hylian Shield is a +1 shield; the Mirror Shield a +2", "Hylian: Shield Attack and Shield Master, and a reaction that takes 1d10+11 off a ranged weapon attack (he catches arrows on it). Mirror: the same, and once a round, as a reaction, a spell that targets only him and allows a saving throw is reflected at the caster instead; fire and light pass back the way they came."),
 ("Fairy Bow, Longshot, bombs, boomerang, Deku Nuts, Lens of Truth", "the dungeon kit", "Above. The Longshot pulls him up to 120 ft to any solid thing, or a Medium or smaller creature to him (Str save DC 18). Bombchus run along walls and ceilings. The Lens shows what is not there and hides what is: truesight for a Magic Point a minute."),
 ("Golden Gauntlets, Iron Boots, Hover Boots, the tunics", "the Spirit, Water and Fire temples' answers", "Golden Gauntlets: his Strength counts as 25 for lifting, carrying, breaking and shoving; he lifted a pillar the size of a tower. Iron Boots: he sinks and cannot be pushed, and walks on the bottom of a lake in the Zora Tunic, which lets him breathe there. Goron Tunic: resistance to fire and he can stand in it. Hover Boots: he crosses a 15-ft gap in the air before he falls."),
 ("The Ocarina of Time", "legendary instrument · a song is an action", "<b>Zelda's Lullaby:</b> opens any door sealed by the royal family, as Knock, and proves who sent him. <b>Epona's Song:</b> Epona comes, a warhorse who outruns anything on the field. <b>Saria's Song:</b> Sending to her. <b>Sun's Song:</b> night to day or back; every undead within 60 ft is Stunned until the end of its next turn. <b>Song of Storms:</b> a storm, as Control Weather, in a minute. <b>Song of Healing:</b> Greater Restoration on a soul, and a cursed or possessed creature's suffering is drawn out of it into a mask. <b>Goron Lullaby:</b> every creature within 60 ft that can hear it, Wis DC 18 or asleep for a minute (damage wakes it); it put a race to sleep. <b>Elegy of Emptiness:</b> a hollow statue of himself, an object with his AC and 30 hit points, that enemies may take for him. <b>Song of Soaring, the six warp songs:</b> Teleport to a place he has stood. <b>Song of Time:</b> what it did in Termina. Once per long rest he can return a fight to the start of his previous turn with everything as it was and only his memory changed; the DM should let the table feel the three days in that. <b>Oath to Order:</b> the Four Giants come. Once."),
 ("The masks", "Termina's", "<b>Deku:</b> Small, hops on water, spits a bubble (+12, 2d4), launches from a Deku flower 60 ft, and Burning kills him. <b>Goron:</b> Str 20, rolls 60 ft a turn as a spiked boulder (3d8 to anything in the path, Dex DC 18), punches 1d10+Str, pounds the ground (10 ft, Str DC 18 or prone), immune to fire, sinks like a stone. <b>Zora:</b> swims 60 ft, breathes water, throws his fins (two boomerangs at +12, 1d6+5), raises an electric barrier (every creature within 5 ft takes 2d8 lightning, 1 Magic a turn). <b>Fierce Deity:</b> only inside a boss's lair. Large; Strength 24 and Constitution 20 while worn; +50 temporary hit points; the Fierce Deity's Sword, +14, 2d10+9 slashing with reach, and it fires a beam 120 ft for 3d10 force on every hit (1 Magic); immune to being Frightened. <b>Bunny Hood:</b> speed 45. <b>Stone Mask:</b> creatures that have not noticed him cannot; it does nothing to one that already has, or to a boss. <b>Giant's Mask:</b> in Twinmold's lair only, Gargantuan. <b>Mask of Truth:</b> Detect Thoughts on anything that can think and a conversation with any Gossip Stone. <b>Blast Mask:</b> a bomb with his face on it, 3d6 fire in 10 ft, half to him unless the shield is up. Captain's Hat, Garo's, Gibdo, Couple's, Kamaro's, Bremen, Romani's, Postman's, Don Gero's, Circus Leader's, Kafei's, All-Night, Keaton, Great Fairy's: they open mouths and doors, not wounds."),
 ("Epona, Navi, the Great Fairy's Sword", "", "Epona: a warhorse with 80-ft speed who comes to a song. Navi: a fairy who marks a target (Advantage on his next attack against a creature she points at, once a turn) and never shuts up. The Great Fairy's Sword, from Termina: a +3 greatsword, 2d6+8, the heaviest blade he ever carried."),
 ("The Hero's Shade", "the variant: Twilight Princess", "Medium Undead (a golden wolf in the field, a Stalfos knight in the training ground). Everything above except the bottles and the Magic Meter; immune to poison, exhaustion and being Frightened; cannot be destroyed, only released. He can teach the seven Hidden Skills to a worthy Fighter, one per visit, each a maneuver the student keeps. He regrets one thing: that nobody remembered him as the hero. Hyrule Historia says who he was.")]
for name, tag, text in hb:
    S.append(KeepTogether([P(name, hb_name), P(tag, hb_tag) if tag else Spacer(1,0), P(text, small)]))
S.append(P("Build, level by level", h2)); S.append(rule())
S.append(P("Point buy 12 / 15 / 14 / 10 / 13 / 8; the Kokiri-foundling background (custom, as the DMG allows) gives +2 Dex, +1 Con, Tough, Acrobatics and Survival and the ocarina; the Hylian is a Human reflavoured, Alert as the Versatile feat and Athletics as the skill.", small))
rows = [("1","Dueling, Second Wind, masteries; Tough, Alert","The boy in the Kokiri Forest, nine years old and the only one without a fairy"),
 ("2","Action Surge, Tactical Mind","Navi. The Great Deku Tree. Gohma"),
 ("3","Battle Master: Spin Attack, Ending Blow, Back Slice; Student of War","Death Mountain and King Dodongo; the Gorons are saved"),
 ("4","Sharpshooter (+1 Dex → 18)","Jabu-Jabu's belly and Barinade; the Zoras are saved. The three Stones"),
 ("5","Extra Attack, Tactical Shift","The Door of Time. He draws the Master Sword, and sleeps for seven years"),
 ("6","Shield Master (+1 Str → 13)","He wakes a man. Rauru. The Hylian Shield fits now"),
 ("7","Know Your Enemy; Helm Splitter, Mortal Draw","The Forest Temple: Phantom Ganon. Saria awakens"),
 ("8","+2 Dexterity (20)","The Fire Temple: Volvagia. Darunia awakens"),
 ("9","Indomitable, Tactical Master","The Water Temple: his own shadow, then Morpha. Ruto awakens"),
 ("10","Improved Combat Superiority (d10); Jump Strike, Great Spin","The Shadow Temple: Bongo Bongo. Impa awakens"),
 ("11","Two Extra Attacks","The Spirit Temple: Twinrova. Nabooru awakens; the Golden Gauntlets"),
 ("12","Athlete (+1 Str → 14)","Ganon's Castle. The Light Arrows from Zelda"),
 ("13","Indomitable ×2, Studied Attacks","Ganondorf, the volley, the tower coming down"),
 ("14","Durable (+1 Con → 16)","Ganon. The Master Sword, lost and returned, and the seal"),
 ("15","Relentless; Shield Attack, Parry","Sent back to be a boy. The search for Navi; the Skull Kid"),
 ("16","Skill Expert (+1 Wis → 15; Perception)","Termina. Three days. Odolwa, Goht, Gyorg, Twinmold; the four masks of the dead"),
 ("17","Action Surge ×2, Indomitable ×3","The Four Giants hold the moon. Majora, and the Fierce Deity"),
 ("18","Ultimate Combat Superiority (d12)","Home to a Hyrule that never knew. A knight; a family"),
 ("19","Boon of Combat Prowess (+1 Wis → 16)","Death, with one regret"),
 ("20","Three Extra Attacks","The Hero's Shade, and the seven Hidden Skills, and rest")]
S.append(grid([[P("Lvl", cellhead), P("What you get", cellhead), P("Where in the story", cellhead)]] + [[P(a, cellb), P(b, cell), P(c, cell)] for a, b, c in rows], [0.4*inch, 3.1*inch, W-3.5*inch]))
S.append(PageBreak()); S.append(P("Snapshots by arc, with the feat checked", h2)); S.append(rule())
def snap(name, where, lvl, lines, checked):
    content = [P(name, snapname), P(where + "  ·  " + lvl, stattag)] + [P(l, snapline) for l in lines] + [P("<b>The feat, checked.</b> " + checked, snapline)]
    t = Table([[content]], colWidths=[W]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("LINEBEFORE",(0,0),(0,-1),2.5,GREEN),("LEFTPADDING",(0,0),(-1,-1),10),("RIGHTPADDING",(0,0),(-1,-1),10),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
    return KeepTogether([t, Spacer(1,7)])
S.append(snap("The boy", "Ocarina of Time, the child era · age nine", "Levels 1–4 · Fighter 1–4", ["Str 12, Dex 17, Con 15, Wis 14 · <b>AC</b> 16 (Deku Shield) · <b>HP</b> 13 → 44 · Kokiri Sword +6, 1d6+5; slingshot +6, 1d4+3; Deku Nuts, bombs, the boomerang; Spin Attack"], "Gohma (CR 3), King Dodongo (CR 5) and Barinade (CR 5) are the three peoples' monsters, and a level-3 boy with a short sword kills each of them the way the game does: with the item the dungeon just handed him. Deku Nuts stun Gohma's eye, bombs go down Dodongo's throat, the boomerang cuts Barinade's tethers, and the sword does the rest. Three races owe him their lives and he is nine."))
S.append(snap("The sleep, and the man who woke", "Ocarina of Time, the adult era · age sixteen to seventeen", "Levels 5–11 · Fighter 5–11", ["Dex 20 by level 8 · <b>AC</b> 20 · <b>HP</b> 59 → 125 · the Master Sword at +12, 1d8+10, three attacks by level 11 · the Hidden Skills arrive as maneuvers · the Fairy Bow, the Longshot, Din's Fire, Farore's Wind, Nayru's Love"], "Seven years in the Sacred Realm is the one level-up in the story that cost him nothing and everything. Then five temples. Phantom Ganon (CR 12) dies to the volley, which is the Master Sword's Reflection card. Volvagia (CR 15) dies to the Megaton Hammer, which is why the hammer knocks prone. Dark Link is his own sheet with a lower level, and the game's trick (hit him when he does not expect it) is a Mortal Draw. Morpha, Bongo Bongo and Twinrova are the Longshot, the Lens of Truth and the Mirror Shield, three items the dungeon kit has for a reason."))
S.append(snap("Ganondorf, and Ganon", "Ocarina of Time · the top of the tower, and the rubble", "Levels 12–14 · Fighter 12–14", ["<b>HP</b> 137 → 164 · Light Arrows · Nayru's Love, if he needs it · Indomitable ×2"], "Ganondorf is a CR 24 caster with the Triforce of Power; the fight is his bolts batted back with the Master Sword's reaction, a Light Arrow that stuns a creature of evil (Con DC 18, and he fails), and a sword that does +2d8 radiant to exactly him. Ganon is the beast, CR 26, with 400 hit points and a tail: the Master Sword is knocked away and he fights it with Biggoron's Sword and the hammer until Zelda holds it down, then the blade comes back and the Ending Blow ends it. A level-14 hero does not beat Ganon alone; the sheet agrees, and so does the game, which is why six Sages and a princess are in the room."))
S.append(snap("Termina", "Majora's Mask · a boy again, with everything he knows", "Levels 15–17 · Fighter 15–17", ["<b>HP</b> 177 → 197 · Relentless, Action Surge ×2 · the Gilded Sword, the Great Fairy's Sword, the masks of the dead"], "Odolwa, Goht, Gyorg and Twinmold are the Deku, Goron, Zora and Giant's masks: the game hands him a dead man's body for each one. The moon is a feat for the Four Giants, not for him; his part is to free them, and the Oath to Order is one line on the Ocarina card because it only ever happens once. Majora's Mask, Incarnation and Wrath are a CR 25 that the Fierce Deity's Mask turns into a two-minute fight: Str 24, a sword with reach, a beam on every hit. The mask works only in a boss's lair, which is the whole reason it is allowed to be that strong."))
S.append(snap("The knight, the grave, the Shade", "Hyrule Historia; Twilight Princess · the rest of his life, and after", "Levels 18–20 · Fighter 18–20, then the Shade", ["<b>HP</b> 224 · d12 dice, four attacks, the Boon · then Undead, and the seven Hidden Skills taught one at a time"], "He went home to a Hyrule where the Ganondorf he beat had never risen, because he had gone back and warned them. Nobody there knew what he had done. He became a knight, had a family, and died regretting that he had not been remembered as a hero and had not passed on what he knew. So he stayed, as a golden wolf and a skeleton in old armor, until his descendant came, and taught him the Ending Blow, the Shield Attack, the Back Slice, the Helm Splitter, the Mortal Draw, the Jump Strike and the Great Spin. Then he could go. That is the last feat on the sheet, and it is the one he was proudest of."))
S.append(P("A DM's dial", h2)); S.append(rule())
S.append(P("Everything above is sized to the games. For a table: Nayru's Love becomes resistance to all damage instead of immunity, the fairy brings him back at 50 hit points instead of 90, Deku Nuts work only on creatures without Legendary Resistance, the Song of Time's rewind is a once-a-campaign favor from the DM, and the Fierce Deity's Mask stays in the boss room where it belongs. That is still the Hero of Time; it is just one who can lose."))
doc.build(S, onFirstPage=on_page, onLaterPages=on_page); print("ok")
